insert into public.diagnostico_items
  (id, area, tipo, peso, elo, elo_base, enunciado, opciones, fen, correcta, solucion, alternas, explica, lichess, rating)
values
  ('tac_senales_combinacion', 'tactica', 'opcion', 3, 1510, 1700, '¿Qué señales avisan de que en una posición probablemente HAY una combinación?', '["Rey con pocas casillas, piezas sin defensa o clavadas.","Tener más material que el rival en ese momento justo.","Que el rival haya movido dos veces la misma pieza.","Que queden menos de veinte piezas en el tablero."]'::jsonb, null, 0, null, null, 'Las combinaciones no aparecen de la nada: viven de elementos concretos. Cuando hay dos o tres de esos elementos juntos, vale la pena gastar tiempo buscando; cuando no hay ninguno, casi nunca hay nada.', null, null),
  ('tac_defensa_activa', 'tactica', 'opcion', 2, 1100, 1700, 'Estás bajo ataque y aguantando. ¿Cuál es el criterio de defensa que más partidas salva?', '["Buscar el contragolpe o cambiar la pieza atacante.","Retirar todas las piezas a la primera fila y esperar.","Devolver material de inmediato para calmar el juego.","Dar jaques hasta que el rival se equivoque solo."]'::jsonb, null, 0, null, null, 'Defender sumando piezas pasivas pierde por acumulación: el atacante sigue trayendo gente. Cambiar a la pieza atacante clave o abrir un frente propio da vuelta muchas más partidas.', null, null),
  ('mate_dos_jugadas', 'mate', 'jugada', 3, 1400, 1450, 'Mate en dos jugadas: juega solo la primera, la que lo fuerza. Aviso: no es jaque.', null, '6k1/5ppp/8/5N1Q/8/8/8/6K1 w - - 0 1', null, '{"from":"h5","to":"g5"}'::jsonb, null, 'Dg5 es una jugada callada: amenaza Dxg7 mate y las negras no tienen forma de cubrirlo todo, porque el caballo de f5 controla las casillas de escape.', null, null),
  ('mate_tres_jugadas', 'mate', 'jugada', 1, 1070, 1700, 'Mate en tres jugadas: juega solo la primera. Tampoco es jaque.', null, '6k1/5p1p/6p1/8/8/7Q/8/4R1K1 w - - 0 1', null, '{"from":"h3","to":"h6"}'::jsonb, null, 'Dh6 mete la dama en la casilla desde donde amenaza mate y le quita al rey la salida por g7. Contra cualquier defensa, la torre entra por la columna e y el mate llega en tres.', null, null),
  ('mate_enroques_opuestos', 'mate', 'opcion', 3, 1580, 1450, 'Partida con enroques opuestos (uno enrocó corto y el otro largo). ¿Qué decide el ataque?', '["La velocidad: gana quien abre una línea primero.","Quién tiene más piezas menores en el ataque.","Quién consigue cambiar las damas antes que el otro.","Quién deja su estructura de peones intacta."]'::jsonb, null, 0, null, null, 'Con enroques opuestos los peones propios ya no defienden al rey: son la artillería. Contar tiempos —cuántas jugadas me faltan a mí y cuántas a él— es literalmente la evaluación de la posición.', null, null),
  ('mate_boden', 'mate', 'opcion', 3, 1620, 1700, '¿Qué piezas dan el mate de Boden y contra qué rey?', '["Dos alfiles cruzados, contra un rey que enrocó largo.","Dama y caballo, contra un rey que quedó en el centro.","Dos torres en columnas contiguas, contra el rey al borde.","Torre y peón, contra un rey tapado por sus piezas."]'::jsonb, null, 0, null, null, 'Aparece después de sacrificar en c3/c6 o a6/a3 para abrir las diagonales. Reconocer el patrón es lo que permite ver el sacrificio tres jugadas antes.', null, null),
  ('fin_lucena', 'finales', 'opcion', 2, 1340, 1450, 'Posición de Lucena: tienes rey, torre y un peón en séptima; tu rey está delante del peón y el rey rival está cortado a dos columnas. ¿Cómo se gana?', '["Construyendo el puente: la torre a la cuarta fila.","Dando jaques con la torre hasta que el rey se aleje.","Adelantando el rey por la columna del peón, sin más.","Cambiando las torres y ganando el final de peones."]'::jsonb, null, 0, null, null, 'Es la técnica de torres que más puntos vale: sin el puente, el mismo final es tablas. La torre en cuarta fila es la jugada que se aprende y ya no se olvida.', null, null),
  ('fin_torre_detras_pasado', 'finales', 'opcion', 3, 1610, 1450, 'Final de torres con un peón pasado. ¿Dónde va la torre, según la regla de Tarrasch?', '["Detrás del peón pasado, la del que empuja y la que frena.","Delante del peón pasado, para bloquearlo con la propia torre.","Al costado del peón, en su misma fila, vigilándolo.","En la columna del rey rival, sin importar el peón."]'::jsonb, null, 0, null, null, 'Detrás, la torre que apoya gana casillas a medida que el peón avanza, y la que frena no pierde ninguna. Delante, el bloqueo condena a la torre a mirar la partida desde ahí.', null, null),
  ('fin_philidor', 'finales', 'opcion', 3, 1520, 1700, 'Defiendes con rey y torre contra rey, torre y un peón que todavía no llegó a tu tercera fila. ¿Cuál es la defensa de Philidor?', '["Torre en la tercera fila y después jaques por detrás.","Cambiar las torres a la primera oportunidad que haya.","Dar jaques desde el costado sin parar, desde el principio.","Poner la torre delante del peón y dejarla quieta."]'::jsonb, null, 0, null, null, 'Son dos etapas y en ese orden: la tercera fila frena al rey, y cuando el peón avanza pierde el escudo, por eso los jaques desde atrás ya no se pueden tapar. Es la defensa que salva medio punto en cada torneo.', null, null),
  ('fin_triangulacion', 'finales', 'opcion', 3, 1650, 1700, 'En un final de reyes y peones, ¿para qué sirve triangular con el rey?', '["Para perder un tiempo y devolverle el turno al rival.","Para llegar antes a la casilla de coronación del peón.","Para atacar el peón rival desde el otro lado.","Para evitar el ahogado del rey contrario."]'::jsonb, null, 0, null, null, 'Es zugzwang fabricado: la posición no cambia, cambia de quién es el turno. Solo funciona si tu rey tiene tres casillas útiles y el del rival no.', null, null),
  ('est_profilaxis', 'estrategia', 'opcion', 2, 1370, 1450, '¿En qué consiste jugar con profilaxis?', '["Preguntarse qué quiere el rival y quitárselo.","Cambiar piezas para no correr ningún riesgo.","Defender el rey antes de empezar cualquier plan.","Repetir jugadas hasta que el rival se decida."]'::jsonb, null, 0, null, null, 'La pregunta de Petrosian: "si me tocara mover a mí dos veces, ¿qué haría él?". Quitarle esa jugada suele valer más que adelantar el propio plan una casilla.', null, null),
  ('est_dos_debilidades', 'estrategia', 'opcion', 4, 1800, 1450, '¿Qué dice el principio de las dos debilidades?', '["Que hace falta una segunda debilidad, en el otro flanco.","Que nunca hay que dejarse dos peones débiles en el tablero.","Que dos piezas mal puestas equivalen a un peón menos.","Que hay que atacar primero la debilidad más grande."]'::jsonb, null, 0, null, null, 'Es cómo se convierte una ventaja chica en punto entero: se fija la primera debilidad, se lleva el juego al otro flanco y la defensa se parte. Sin la segunda, casi todo se aguanta.', null, null),
  ('est_espacio_cambios', 'estrategia', 'opcion', 2, 1300, 1700, 'Tienes menos espacio que tu rival. ¿Qué conviene hacer?', '["Cambiar piezas: las que quedan tienen más aire.","Evitar todos los cambios para no simplificar.","Avanzar los peones donde tienes menos espacio.","Enrocar al lado contrario y salir a atacar."]'::jsonb, null, 0, null, null, 'Con poco espacio el problema no son las piezas del rival: son las propias, que se estorban. El que tiene más espacio evita los cambios por la misma razón.', null, null),
  ('est_plan_desde_estructura', 'estrategia', 'opcion', 2, 1330, 1700, 'Llegas a una posición que no conoces y no sabes qué hacer. ¿De dónde sale el plan?', '["De la estructura de peones: rupturas y casillas débiles.","De la apertura jugada, aunque la estructura haya cambiado.","De contar el material y elegir el flanco con más piezas.","De dar jaque para ver cómo responde el rival y decidir."]'::jsonb, null, 0, null, null, 'Los peones son lo único que casi no vuelve atrás: definen el terreno. Leer la estructura antes de mover piezas es la diferencia entre tener un plan y hacer jugadas.', null, null),
  ('cal_posicion_critica', 'calculo', 'opcion', 2, 1350, 1450, 'En una partida lenta, ¿dónde hay que gastar el tiempo de reflexión?', '["En las posiciones críticas, donde la partida se define.","Repartido parejo entre todas las jugadas de la partida.","En la apertura, para salir bien de las primeras quince.","En el final, que es cuando se puede calcular todo."]'::jsonb, null, 0, null, null, 'Reconocer la posición crítica —una ruptura, un cambio que no vuelve atrás, el momento de atacar— y ahí pensar veinte minutos es lo que separa a quien administra bien el reloj.', null, null),
  ('cal_comparar_finales', 'calculo', 'opcion', 2, 1330, 1450, 'Dos jugadas te parecen buenas y no llegas a calcularlas hasta el final. ¿Cómo decides?', '["Comparando las posiciones a las que llevan las dos.","Eligiendo la que da jaque, que siempre es más fuerte.","Eligiendo la que gana más material en la primera jugada.","Repitiendo la posición para decidir con más tiempo."]'::jsonb, null, 0, null, null, 'El cálculo termina en una evaluación, no en un número: cuando no se ve el final de la variante, se compara la posición que queda. Calcular sin evaluar no sirve de nada.', null, null),
  ('cal_jugadas_silenciosas', 'calculo', 'opcion', 2, 1340, 1700, '¿Qué tipo de jugada es la que más se escapa cuando uno calcula?', '["Las silenciosas: ni jaque ni captura, y las del rival.","Los jaques, porque en cada posición hay muchos.","Las capturas de peón, que parecen todas iguales entre sí.","Las jugadas de enroque, que cambian dos piezas."]'::jsonb, null, 0, null, null, 'El cálculo se apoya en lo forzado, y ahí la vista funciona sola. Las combinaciones que uno no ve casi siempre terminan en una jugada callada — propia o del rival.', null, null),
  ('cal_orden_del_arbol', 'calculo', 'opcion', 3, 1580, 1700, 'Al calcular una variante larga, ¿qué hace un jugador fuerte para no perderse?', '["Recorre una rama entera y vuelve a la posición inicial.","Calcula todas las variantes a la vez para no olvidar ninguna.","Mira la primera jugada de cada variante y elige por intuición.","Avanza siempre hacia adelante y nunca vuelve atrás."]'::jsonb, null, 0, null, null, 'Saltar de rama en rama es lo que produce esas alucinaciones donde una pieza queda en dos lados. Una rama, evaluación, vuelta al inicio: es lento al principio y después es la única forma de calcular limpio.', null, null),
  ('reg_forma_l', 'reglas', 'opcion', 1, 530, 700, '¿Qué pieza se mueve siempre en forma de «L»?', '["El caballo","El alfil","La torre","La dama"]'::jsonb, null, 0, null, null, 'El caballo es la única que se mueve en «L» —dos casillas en una dirección y una perpendicular— y la única que salta por encima de las demás.', null, null),
  ('reg_h1_clara', 'reglas', 'opcion', 1, 680, 700, 'En la posición inicial, ¿de qué color es la casilla h1 y qué regla lo resume?', '["Clara: «casilla clara a la derecha»","Oscura: «casilla oscura a la derecha»","Clara: «la dama se viste de su color»","Oscura: «el rey siempre en casilla clara»"]'::jsonb, null, 0, null, null, '«Casilla clara a la derecha»: vista desde las blancas, la esquina de abajo a la derecha del tablero siempre es clara. Si sale oscura, el tablero está mal puesto.', null, null),
  ('reg_notacion_enroque', 'reglas', 'opcion', 1, 890, 700, '¿Cómo se anota en notación algebraica el enroque corto?', '["O-O","0-0","E.C.","O-O-O"]'::jsonb, null, 0, null, null, 'El enroque corto se anota O-O, con la letra O; el largo, O-O-O. Se escriben con letra, no con el número cero.', null, null),
  ('reg_al_paso_cuando', 'reglas', 'opcion', 2, 1220, 950, 'Un peón blanco en e5 puede capturar «al paso» a un peón negro que…', '["Acaba de avanzar dos casillas, de d7 a d5","Acaba de avanzar una casilla, de d6 a d5","Lleva varias jugadas quieto, parado en d5","Avanzó una sola casilla, de d7 hasta d6"]'::jsonb, null, 0, null, null, 'La captura al paso solo es legal en la jugada inmediatamente siguiente al avance doble del peón rival. Si se deja pasar un turno, el derecho se pierde.', null, null),
  ('reg_ahogado_resultado', 'reglas', 'opcion', 1, 790, 950, 'Si el jugador en turno no tiene el rey en jaque, pero no le queda ninguna jugada legal, la partida es…', '["Tablas por ahogado","Derrota inmediata","Repetición de turno","Jaque mate"]'::jsonb, null, 0, null, null, 'Esa situación se llama ahogado (stalemate) y el resultado son tablas, no una derrota. Con ventaja aplastante hay que vigilarla: es la forma más común de dejar escapar una partida ganada.', null, null),
  ('reg_enroque_condicion_falsa', 'reglas', 'opcion', 2, 1160, 1200, '¿Cuál de estas condiciones NO hace falta para poder enrocar?', '["Que al rival le queden menos de cinco minutos","Que el rey y esa torre no se hayan movido nunca","Que no quede ninguna pieza entre el rey y la torre","Que el rey no esté en jaque ni pase por uno"]'::jsonb, null, 0, null, null, 'El reloj del rival no tiene nada que ver con la legalidad del enroque. Las tres condiciones reales son las otras: que ni el rey ni esa torre se hayan movido, que no haya piezas entre medio, y que el rey no esté en jaque ni pase ni termine en casilla atacada.', null, null),
  ('reg_enroque_largo_torre', 'reglas', 'opcion', 2, 1200, 950, '¿Qué torre participa en el enroque largo?', '["La torre de la columna «a»","La torre de la columna «h»","Cualquiera de las dos torres","Ninguna: solo se mueve el rey"]'::jsonb, null, 0, null, null, 'El enroque largo (O-O-O) lleva el rey hacia el flanco de dama y usa la torre de la columna «a»; el corto (O-O) usa la de la columna «h». Se llama largo porque la torre recorre una casilla más.', null, null),
  ('reg_triple_repeticion', 'reglas', 'opcion', 1, 690, 950, 'Si la misma posición se repite tres veces, con el mismo jugador en turno y los mismos derechos (enroque, al paso), ¿qué puede reclamar un jugador?', '["Tablas por triple repetición","Una jugada extra de regalo","La victoria automática","Nada: la partida sigue igual"]'::jsonb, null, 0, null, null, 'La repetición no tiene que ser en jugadas seguidas, y da derecho a reclamar tablas sin importar quién esté mejor en el tablero. Ojo: se reclama, no se declara sola.', null, null),
  ('reg_50_jugadas', 'reglas', 'opcion', 1, 1070, 1200, '¿Qué dice la «regla de las 50 jugadas»?', '["Sin captura ni jugada de peón en 50, hay tablas","Una partida no puede pasar de 50 jugadas en total","Cada jugador tiene 50 segundos para cada jugada","Después de la jugada 50 la dama pierde valor"]'::jsonb, null, 0, null, null, 'Si pasan 50 jugadas seguidas de cada bando sin ninguna captura y sin mover ningún peón, cualquiera de los dos puede reclamar tablas. Existe para que una posición sin progreso no se estire para siempre.', null, null),
  ('reg_material_insuficiente', 'reglas', 'opcion', 1, 890, 1200, '¿Cuál de estos finales es tablas automáticas por material insuficiente para dar mate?', '["Rey y alfil contra rey solo","Rey y dos torres contra rey","Rey y dama contra rey solo","Rey y dos alfiles contra rey"]'::jsonb, null, 0, null, null, 'Con rey y un alfil —o rey y un caballo— no existe ninguna red de mate posible contra el rey solo, así que la partida es tablas de inmediato. Con dos torres, con dama o con dos alfiles sí se da mate.', null, null),
  ('reg_pieza_tocada', 'reglas', 'opcion', 1, 670, 950, 'En una partida con la regla de «pieza tocada, pieza jugada», si tocas una pieza propia con intención de moverla…', '["Tienes que moverla si tiene alguna jugada legal","Puedes cambiar de idea sin ninguna consecuencia","Pierdes la partida en ese mismo momento","Debes capturarla tú mismo con otra pieza"]'::jsonb, null, 0, null, null, 'La regla de torneo obliga a mover la pieza que se tocó, siempre que tenga alguna jugada legal. Por eso, para acomodar una pieza torcida sin comprometerse, primero hay que avisar «compongo».', null, null),
  ('reg_compongo', 'reglas', 'opcion', 1, 930, 950, '¿Para qué sirve decir «compongo» (j''adoube) antes de tocar una pieza?', '["Para acomodarla sin quedar obligado a moverla","Para ofrecerle tablas al rival en ese momento","Para anunciar que la jugada siguiente da mate","Para pedir unos minutos más en el reloj"]'::jsonb, null, 0, null, null, 'Avisa al rival de que vas a enderezar una pieza mal colocada en su casilla, y que eso no cuenta como haberla tocado para moverla. Hay que decirlo ANTES de tocarla, nunca después.', null, null),
  ('reg_cuantas_piezas', 'reglas', 'opcion', 1, 510, 700, '¿Cuántas piezas tiene cada jugador al empezar la partida, contando los peones?', '["16","12","20","24"]'::jsonb, null, 0, null, null, 'Cada bando empieza con 16: un rey, una dama, dos torres, dos alfiles, dos caballos y ocho peones. Entre los dos, 32 piezas en 64 casillas: justo la mitad del tablero ocupada.', null, null),
  ('reg_peon_captura', 'reglas', 'opcion', 1, 670, 700, '¿Cómo captura un peón a una pieza rival?', '["En diagonal, una casilla hacia adelante","En línea recta, igual que cuando avanza","Hacia atrás y en diagonal, una casilla","No captura: el peón solamente avanza"]'::jsonb, null, 0, null, null, 'El peón avanza recto pero captura en diagonal, y esa diferencia explica media estrategia de peones: una pieza justo enfrente lo bloquea sin estar en peligro, y en cambio no está a salvo en las dos diagonales.', null, null),
  ('reg_peon_primer_salto', 'reglas', 'opcion', 1, 650, 700, 'Un peón que todavía no se ha movido, ¿cuántas casillas puede avanzar en su primera jugada?', '["Una o dos, a elección","Solo una, nunca dos","Siempre dos casillas","Hasta tres casillas"]'::jsonb, null, 0, null, null, 'Solo en su primer movimiento el peón puede elegir entre una casilla y dos; de ahí en adelante avanza de una en una. Y ese avance doble es justamente el que habilita la captura al paso del rival.', null, null),
  ('reg_caida_bandera', 'reglas', 'opcion', 1, 1010, 1450, 'Si a un jugador se le acaba el tiempo en el reloj, ¿qué pasa normalmente?', '["Pierde, salvo que el rival no pueda dar mate nunca","Son tablas siempre, sin ninguna excepción","El reloj se reinicia y la partida continúa igual","Gana de inmediato quien se quedó sin tiempo"]'::jsonb, null, 0, null, null, 'Quedarse sin tiempo pierde la partida, con una excepción: si al rival no le queda material con el que dar mate en ninguna secuencia posible —por ejemplo, si solo le queda el rey—, el resultado son tablas.', null, null),
  ('reg_jaque_perpetuo', 'reglas', 'opcion', 1, 1040, 1200, '¿Qué es el «jaque perpetuo» como recurso defensivo?', '["Jaques seguidos que el rival no puede evitar","Un jaque que gana la partida en el acto mismo","Un mate especial que solo se da con la dama","Un tipo de enroque que se hace estando en jaque"]'::jsonb, null, 0, null, null, 'Cuando un bando está perdido, a veces puede salvarse dando jaques sin parar: si el rey rival no tiene forma de escapar de esa cadena, la posición se repite y la partida termina en tablas.', null, null),
  ('reg_columnas_filas', 'reglas', 'opcion', 2, 1310, 700, 'En la notación algebraica, ¿cómo se nombran las columnas y las filas del tablero?', '["Columnas con letras y filas con números","Columnas con números y filas con letras","Las dos con números, del 1 hasta el 8","Las dos con letras, de la «a» a la «h»"]'::jsonb, null, 0, null, null, 'Cada casilla se nombra por su columna (letra, de la «a» a la «h») y su fila (número, del 1 al 8): e4 es la columna «e», fila 4. Siempre en ese orden, primero la letra.', null, null),
  ('reg_dama_su_color', 'reglas', 'opcion', 1, 830, 950, 'Regla mnemotécnica clásica sobre dónde empieza cada dama: «la dama se coloca…»', '["…en su color: la blanca en clara, la negra en oscura","…siempre en una casilla oscura, sea del color que sea","…siempre en la columna «e», justo al lado del rey","…enfrente de la dama rival, siempre en diagonal"]'::jsonb, null, 0, null, null, '«La dama se viste de su color»: la blanca empieza en d1, que es casilla clara, y la negra en d8, que es oscura. Es la forma más rápida de comprobar que el tablero y las piezas están bien puestos.', null, null),
  ('reg_notacion_captura', 'reglas', 'opcion', 1, 560, 700, 'En notación algebraica, ¿qué indica la letra «x» dentro de una jugada, por ejemplo «Axf6»?', '["Que esa jugada es una captura","Que el peón corona en dama","Que la jugada da jaque","Que se trata de un enroque corto"]'::jsonb, null, 0, null, null, 'La «x» marca siempre una captura: «Axf6» quiere decir que el alfil capturó una pieza rival en f6. El jaque se anota con «+» y la coronación con «=», que son otros signos.', null, null),
  ('reg_varias_damas', 'reglas', 'opcion', 1, 690, 1200, '¿Puede un jugador llegar a tener más de una dama al mismo tiempo en el tablero?', '["Sí: coronando un peón mientras conserva la suya","No: cada bando tiene una sola dama en la partida","Solo si la dama original ya fue capturada antes","Solo en partidas de ajedrez rápido y relámpago"]'::jsonb, null, 0, null, null, 'Coronar no reemplaza a la dama original: si todavía la tienes en el tablero y coronas otro peón, terminas con dos damas, y coronando más, con tres o cuatro. No hay ningún tope en el reglamento.', null, null),
  ('reg_tablas_acuerdo', 'reglas', 'opcion', 2, 1330, 950, '¿Cómo se pueden acordar tablas entre los dos jugadores, sin que se dé ninguna de las otras reglas de tablas?', '["Uno las ofrece y el otro las acepta","Solo el árbitro puede decretarlas","No existen: solo hay tablas por regla","Los dos se quedan sin tiempo a la vez"]'::jsonb, null, 0, null, null, 'En cualquier momento un jugador puede ofrecer tablas —lo correcto es hacerlo después de mover y antes de apretar el reloj— y, si el rival acepta, la partida termina ahí por acuerdo mutuo.', null, null),
  ('reg_alfil_diagonal', 'reglas', 'opcion', 1, 610, 700, 'Un alfil se mueve siempre…', '["En diagonal, tantas casillas como estén libres","En línea recta, igual que se mueve la torre","Formando una «L», como hace el caballo","Una sola casilla por turno, en cualquier lado"]'::jsonb, null, 0, null, null, 'Va en diagonal todo lo que quiera mientras el camino esté libre, y por eso nunca cambia de color de casilla: el alfil que empieza en casilla clara se queda en las claras toda la partida.', null, null),
  ('mat_valor_peon', 'material', 'opcion', 1, 650, 700, '¿Cuál es el valor aproximado de un peón?', '["1","3","5","9"]'::jsonb, null, 0, null, null, 'El peón es la unidad con la que se mide todo lo demás: vale 1 punto.', null, null),
  ('mat_valor_caballo', 'material', 'opcion', 1, 610, 700, '¿Cuál es el valor aproximado de un caballo?', '["1","3","5","9"]'::jsonb, null, 1, null, null, 'Caballo y alfil valen unos 3 peones cada uno. Son las llamadas piezas menores.', null, null),
  ('mat_valor_torre', 'material', 'opcion', 1, 640, 700, '¿Cuál es el valor aproximado de una torre?', '["1","3","5","9"]'::jsonb, null, 2, null, null, 'La torre vale unos 5 peones: dos peones más que una pieza menor, y esa diferencia es lo que se llama «la calidad».', null, null),
  ('mat_valor_alfil', 'material', 'opcion', 1, 700, 700, '¿Cuál es el valor aproximado de un alfil?', '["1","3","5","9"]'::jsonb, null, 1, null, null, 'El alfil vale unos 3 peones, igual que el caballo, aunque su fuerza real depende mucho de si la posición está abierta o cerrada.', null, null),
  ('mat_calidad_cambio', 'material', 'opcion', 1, 830, 950, 'Si cambias tu torre (5 puntos) por el alfil (3 puntos) del rival, ¿qué acabas de hacer?', '["Un mal cambio: perdiste la calidad","Un buen cambio, que te deja mejor","Un cambio exactamente igualado","Una jugada que gana la partida ya"]'::jsonb, null, 0, null, null, 'Cambiar una torre por una pieza menor se llama «perder la calidad»: cediste unos 2 puntos de material. A veces compensa —si a cambio consigues una posición mucho mejor—, pero por sí solo es una pérdida.', null, null),
  ('mat_valor_rey', 'material', 'opcion', 1, 1000, 950, '¿Qué valor en puntos se le asigna al rey en las tablas de valores de material?', '["Ninguno: no se puede capturar ni cambiar","El mismo que la dama, que son 9 puntos","El mismo que la torre, que son 5 puntos","Cero puntos, porque no sirve para atacar"]'::jsonb, null, 0, null, null, 'Al rey no se le da valor de cambio porque nunca puede capturarse ni entregarse: la partida termina antes. Eso no quiere decir que sea débil — en los finales es una pieza atacante de primera.', null, null),
  ('mat_piezas_menores', 'material', 'opcion', 1, 790, 700, '¿Cómo se llama, en conjunto, a los alfiles y los caballos?', '["Piezas menores","Piezas mayores","Piezas pesadas","Piezas centrales"]'::jsonb, null, 0, null, null, 'Se agrupan como piezas menores por su valor parecido, unos 3 puntos. Torres y dama son las piezas mayores o pesadas.', null, null),
  ('mat_piezas_mayores', 'material', 'opcion', 1, 670, 700, '¿Cómo se llama, en conjunto, a las torres y la dama?', '["Piezas mayores, o pesadas","Piezas menores del tablero","Piezas centrales del tablero","Piezas pasivas de la partida"]'::jsonb, null, 0, null, null, 'Torres y dama son las piezas mayores —también llamadas pesadas—: tienen más valor y mucho más alcance que alfiles y caballos.', null, null),
  ('mat_sacrificio', 'material', 'opcion', 1, 680, 950, '¿Qué es un «sacrificio» en ajedrez?', '["Entregar material a cambio de otra ventaja","Perder una pieza por un descuido al calcular","Cambiar dos piezas que valen exactamente igual","Abandonar la partida antes de que termine"]'::jsonb, null, 0, null, null, 'Lo que define al sacrificio es que es deliberado: se entrega material porque lo que se recibe a cambio —un ataque, la iniciativa, un mate forzado— vale más que los puntos cedidos. Perder una pieza por descuido no es sacrificar.', null, null)
